/* Original Canvas2D implementation of the supplied 21st.dev recipes.
   Only the two requested modes are selected: ordered dither and matrix.
   No third-party runtime or shader code is required. */
(() => {
  const W=960,H=430, clamp=(v,a=0,b=255)=>Math.max(a,Math.min(b,v));
  const bayer=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];
  const photo=new Image();photo.src='data:image/jpeg;base64,';
  const brianPhoto=new Image();brianPhoto.src='data:image/jpeg;base64,';
  const recipes={creation:{renderMode:'dither',cellSize:9,coverage:100,density:20,contrast:158,bgMode:'blur',bgBlur:60,bgOpacity:100,animStyle:'pulse',animSpeed:100,animIntensity:60},amber:{renderMode:'matrix',cellSize:14,coverage:100,density:15,contrast:115,bgMode:'solid',tint:'#F5B944',tintOpacity:100,overlayBlend:'color',scanLines:30,bloom:30,animStyle:'shimmer',animSpeed:40,animIntensity:15,shaderSource:{preset:'waves',colors:['#2B1A06','#B86E00','#F5B944','#2B1A06'],speed:14,zoom:50,intensity:55,paramA:50,warp:0,detail:50,contrast:45,brightness:50,saturation:50,vignette:20,grain:6,seed:11}}};
  const make=()=>{const c=document.createElement('canvas');c.width=W;c.height=H;return c;};
  const source=make(),s=source.getContext('2d',{willReadFrequently:true});
  const layer=make(),l=layer.getContext('2d');
  const base=make(),b=base.getContext('2d');
  let samples;
  const contrast=(c,f)=>clamp((c-127.5)*f+127.5);
  function initPhoto(){
    const z=Math.max(W/photo.width,H/photo.height),dw=photo.width*z,dh=photo.height*z;
    s.drawImage(photo,(W-dw)/2,(H-dh)/2,dw,dh);
    const pixels=s.getImageData(0,0,W,H).data;samples=[];
    for(let y=0;y<H;y+=9)for(let x=0;x<W;x+=9){let r=0,g=0,bl=0,n=0;
      for(let yy=y;yy<Math.min(y+9,H);yy++)for(let xx=x;xx<Math.min(x+9,W);xx++){const i=(yy*W+xx)*4;r+=pixels[i];g+=pixels[i+1];bl+=pixels[i+2];n++;}
      samples.push({x,y,r:r/n,g:g/n,b:bl/n});
    }
    b.filter='blur(60px)';b.drawImage(source,-60,-27,W+120,H+54);b.filter='none';
  }
  let brianSamples;
  const brianBase=document.createElement('canvas');brianBase.width=640;brianBase.height=640;
  function initBrian(){
    const c=document.createElement('canvas');c.width=640;c.height=640;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(brianPhoto,0,0,640,640);
    const data=cx.getImageData(0,0,640,640).data;brianSamples=[];
    for(let y=0;y<640;y+=9)for(let x=0;x<640;x+=9){let r=0,g=0,b=0,n=0;for(let yy=y;yy<Math.min(y+9,640);yy++)for(let xx=x;xx<Math.min(x+9,640);xx++){const i=(yy*640+xx)*4;r+=data[i];g+=data[i+1];b+=data[i+2];n++;}brianSamples.push({x,y,r:r/n,g:g/n,b:b/n});}
    const bx=brianBase.getContext('2d');bx.filter='blur(60px)';bx.drawImage(c,-40,-40,720,720);bx.filter='none';
  }
  function brian(ctx,time){
    ctx.clearRect(0,0,640,640);ctx.drawImage(brianBase,0,0);const pulse=1+.6*.18*Math.sin(time*Math.PI/2);
    for(const c of brianSamples){const r=contrast(c.r,1.58),g=contrast(c.g,1.58),b=contrast(c.b,1.58),lum=clamp((.2126*r+.7152*g+.0722*b)*pulse)/255,ink=.2+.8*(1-lum);
      ctx.fillStyle=`rgb(${r*.95},${g*.95},${b*.95})`;ctx.fillRect(c.x,c.y,9,9);
      for(let yy=0;yy<4;yy++)for(let xx=0;xx<4;xx++)if(ink>(bayer[yy*4+xx]+.5)/16){ctx.fillStyle='rgba(9,12,18,.86)';ctx.fillRect(c.x+xx*2.25,c.y+yy*2.25,1.8,1.8);}
    }
  }
  function creation(ctx,time){
    ctx.clearRect(0,0,W,H);ctx.drawImage(base,0,0);const pulse=1+.6*.18*Math.sin(time*Math.PI/2);
    l.clearRect(0,0,W,H);
    for(const c of samples){const r=contrast(c.r,1.58),g=contrast(c.g,1.58),bl=contrast(c.b,1.58),lum=clamp((.2126*r+.7152*g+.0722*bl)*pulse)/255;
      // 20% density sets the dark ink floor; ordered subcell dots encode luminance.
      const ink=.2+.8*(1-lum);
      l.fillStyle=`rgb(${r*.95},${g*.95},${bl*.95})`;l.fillRect(c.x,c.y,9,9);
      for(let yy=0;yy<4;yy++)for(let xx=0;xx<4;xx++)if(ink>(bayer[yy*4+xx]+.5)/16){l.fillStyle='rgba(9,12,18,.86)';l.fillRect(c.x+xx*2.25,c.y+yy*2.25,1.8,1.8);}
    }
    ctx.drawImage(layer,0,0);
  }
  const palette=[[43,26,6],[184,110,0],[245,185,68],[43,26,6]];
  function wave(x,y,t){const nx=x/W,ny=y/H;
    const v=.5+.55*(Math.sin(nx*8+ny*3+t*.14*2*Math.PI)*.28+Math.sin(ny*10-nx*4+t*.14*Math.PI)*.2+Math.cos(nx*13+ny*8-t*.22)*.12);
    return clamp((v-.5)*.9+.5,0,1);
  }
  function rgbWave(x,y,t){const v=wave(x,y,t),q=v*3,j=Math.min(2,Math.floor(q)),f=q-j;return palette[j].map((c,k)=>c*(1-f)+palette[j+1][k]*f);}
  function amber(ctx,time){
    ctx.fillStyle='#2B1A06';ctx.fillRect(0,0,W,H);l.clearRect(0,0,W,H);
    l.font='14px "DejaVu Sans Mono", Consolas, monospace';l.textAlign='center';l.textBaseline='middle';
    const chars='0123456789ABCDEF{}<>/+$*';const columns=Math.ceil(W/14),rows=Math.ceil(H/14);
    for(let col=0;col<columns;col++)for(let row=0;row<rows;row++){
      const x=col*14,y=row*14;let rgb=[0,0,0];
      for(const [dx,dy] of [[3,3],[10,3],[3,10],[10,10]]){const v=rgbWave(x+dx,y+dy,time);rgb=rgb.map((c,k)=>c+v[k]/4);}
      const lum=(.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2])/255;
      const head=(time*(2+Math.sin(col*4.7)*.8)*.4+col*7.13)%rows;
      const trail=(head-row+rows)%rows;const rain=trail<15?Math.pow(1-trail/15,1.7):.035;
      const shimmer=1+.15*Math.sin(time*.8+col*.7+row*.21);
      const level=clamp((lum*.65+rain*.7-.5)*1.15+.5,0,1)*shimmer;
      const v=clamp(level*.9+.11,0,1);
      // Green matrix luminance recolored to the supplied amber hue (color blend).
      l.fillStyle=`rgba(${Math.round(245*v)},${Math.round(185*v)},${Math.round(68*v)},${clamp(.18+rain*.82,0,1)})`;
      const hash=Math.abs(Math.floor(Math.sin(col*127.1+row*311.7+Math.floor(time*2.4))*43758.5453));
      l.fillText(chars[hash%chars.length],x+7,y+7);
    }
    ctx.drawImage(layer,0,0);ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=.3;ctx.filter='blur(5px)';ctx.drawImage(layer,0,0);ctx.restore();
    // scanLines 30; source-only vignette20 and grain6.
    ctx.fillStyle='rgba(0,0,0,.15)';for(let y=0;y<H;y+=4)ctx.fillRect(0,y,W,1);
    const v=ctx.createRadialGradient(W/2,H/2,H*.1,W/2,H/2,W*.6);v.addColorStop(0,'transparent');v.addColorStop(1,'rgba(0,0,0,.2)');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
  }
  function redrain(ctx,time){
    const w=ctx.canvas.width,h=ctx.canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#fffdfb';ctx.fillRect(0,0,w,h);
    ctx.font='13px "DejaVu Sans Mono",Consolas,monospace';ctx.textAlign='center';ctx.textBaseline='middle';
    const rows=Math.ceil(h/16),cols=Math.ceil(w/16),chars='0123456789ABCDEF{}<>/+=;';
    for(let col=0;col<cols;col++){const head=(time*(3.8+Math.sin(col*3.1)*1.2)+col*7.91)%rows;
      for(let row=0;row<rows;row++){const trail=(head-row+rows)%rows;if(trail>13)continue;const light=Math.pow(1-trail/13,1.1);const k=Math.abs(Math.floor(Math.sin(col*91.17+row*13.23+Math.floor(time*3))*87953.4))%chars.length;
        ctx.fillStyle=`rgba(236,20,37,${.08+light*.8})`;ctx.fillText(chars[k],col*16+8,row*16+8);
      }
    }
  }
  const ready=Promise.all([photo.decode().then(initPhoto),brianPhoto.decode().then(initBrian)]);
  window.profileEffects={ready,render(kind,canvas,time){const ctx=canvas.getContext('2d');(kind==='creation'?creation:kind==='brian'?brian:kind==='redrain'?redrain:amber)(ctx,time);},recipes};
  ready.then(()=>{
    const targets=[...document.querySelectorAll('canvas[data-effect]')];targets.forEach(c=>{c.width=c.dataset.effect==='brian'?640:W;c.height=c.dataset.effect==='brian'?640:H;});
    const reduced=matchMedia('(prefers-reduced-motion: reduce)'),active=new Set();let raf=0,last=0,elapsed=0;
    function wake(){if(!raf&&!document.hidden&&active.size)raf=requestAnimationFrame(tick);}
    function tick(now){raf=0;if(document.hidden||!active.size)return;if(now-last>65){if(!reduced.matches)elapsed+=Math.min(.15,(now-last)/1000);active.forEach(c=>window.profileEffects.render(c.dataset.effect,c,elapsed));last=now;}if(!reduced.matches)wake();}
    const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)active.add(e.target);else active.delete(e.target);});if(!active.size){cancelAnimationFrame(raf);raf=0;}else wake();},{rootMargin:'60px'});targets.forEach(c=>obs.observe(c));
    document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else{last=performance.now();wake();}});reduced.addEventListener('change',()=>{last=0;wake();});

  }).catch(()=>document.querySelectorAll('canvas[data-effect]').forEach(c=>c.replaceWith(Object.assign(document.createElement('img'),{src:`assets/${c.dataset.effect}-effect.gif`,alt:c.getAttribute('aria-label')}))));
})();
